from pathlib import Path
from textwrap import dedent

BASE = Path(__file__).parent

def I(name): return f'<span data-icon="{name}"></span>'
def badge(text, kind='open'): return f'<span class="badge badge-{kind}">{text}</span>'
def avatar(initials='RK', cls='vendor'): return f'<span class="avatar {cls}">{initials}</span>'
def btn(label, icon=None, cls='btn-primary', href=None, attrs=''):
    inside = (I(icon) if icon else '') + label
    return f'<a class="btn {cls}" href="{href}" {attrs}>{inside}</a>' if href else f'<button type="button" class="btn {cls}" {attrs}>{inside}</button>'
def attachment(name, size='2.4 MB', icon='image'):
    return f'<a class="attachment" href="#" data-toast="Opening {name}">{I(icon)}<span><strong>{name}</strong><span>{size}</span></span>{I("eye")}</a>'
def pagination(total='Showing 1–6 of 24 results'):
    return f'''<div class="pagination"><span>{total}</span><div class="page-buttons"><button class="page-btn" data-page="previous">{I('chevron')}</button><button class="page-btn active" data-page="1">1</button><button class="page-btn" data-page="2">2</button><button class="page-btn" data-page="3">3</button><button class="page-btn" data-page="next">{I('chevron')}</button></div></div>'''
def upload(pid, accept='image/*,.pdf,.doc,.docx', text='Click to upload or drag and drop', hint='PNG, JPG, PDF or DOC up to 10 MB'):
    return f'''<label class="upload-zone"><span class="upload-icon">{I('upload')}</span><p><span>{text}</span></p><small>{hint}</small><input type="file" multiple accept="{accept}" data-preview="{pid}"></label><div class="preview-list" id="{pid}"></div>'''
def modal(mid, title, body, action='Save', action_attrs='data-toast="Saved" data-modal-close'):
    return f'''<div class="modal-backdrop" id="{mid}" role="dialog" aria-modal="true"><div class="modal"><div class="modal-head"><h3>{title}</h3><button class="modal-close" data-modal-close>{I('x')}</button></div><div class="modal-body">{body}</div><div class="modal-actions"><button class="btn btn-secondary" data-modal-close>Cancel</button><button class="btn btn-primary" {action_attrs}>{action}</button></div></div></div>'''
def shell(title, key, content, root='', extra=''):
    return dedent(f'''<!doctype html>
    <html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Fixora user Portal — {title}"><title>{title} · Fixora user</title><link rel="stylesheet" href="{root}assets/styles.css"><script defer src="{root}assets/app.js"></script></head>
    <body data-page="{key}" data-title="{title}" data-root="{root}"><div class="app-shell"><div id="sidebar-root"></div><div class="workspace"><div id="topbar-root"></div><main class="page">{content}</main></div></div>{extra}</body></html>''')
def write(path, title, key, content, extra=''):
    p=BASE/path; p.parent.mkdir(parents=True,exist_ok=True); root='../' if '/' in path else ''; p.write_text(shell(title,key,dedent(content),root,extra),encoding='utf-8')

