# Helpers for vendor cards
def vendor_card(name, initials, vtype, rating, reviews, exp, price, eta, loc='Ranchi', accept_quick=True):
    action = f'<button class="btn btn-primary" data-accept-quick="{name}">Accept Vendor</button>' if accept_quick else f'<button class="btn btn-primary" data-select-job="{name}">{I("plus")} Select Vendor</button>'
    amount = int(price.replace(',',''))
    priceband = 'under1500' if amount < 1500 else ('1500to1800' if amount <= 1800 else 'over1800')
    expband = '10plus' if int(exp.split()[0]) >= 10 else 'under10'
    return f'''<article class="card vendor-card" data-row data-price="{price.replace(',','')}" data-priceband="{priceband}" data-rating="{rating}" data-experience="{exp.split()[0]}" data-expband="{expband}" data-availability="available" data-search="{name} {vtype} {loc}"><div class="vendor-top">{avatar(initials,'md vendor')}<div class="vendor-meta"><h3>{name} <span class="verified">{I('check')}</span></h3><div class="meta-line"><span>{vtype}</span><span>•</span><span class="rating"><span class="star">★</span>{rating} ({reviews})</span><span>•</span><span>{loc}</span></div></div>{badge('Available','success')}</div><div class="vendor-stats"><div class="vendor-stat"><strong>{exp}</strong><span>Experience</span></div><div class="vendor-stat"><strong>168</strong><span>Completed jobs</span></div><div class="vendor-stat"><strong>96%</strong><span>On time</span></div></div><div class="price-row"><div><span class="price">₹{price}</span><div class="small muted">Quotation amount</div></div><div class="text-right"><strong>{eta}</strong><div class="small muted">Est. completion</div></div></div><p class="small muted">Includes inspection, labour and basic consumables. Any replacement parts will be confirmed before purchase.</p><div class="vendor-actions"><a class="btn btn-secondary" href="../vendors/details.html">View Vendor</a><a class="btn btn-secondary" href="quotation-details.html">View Quotation</a><a class="btn btn-soft" href="../messages/chat.html">Chat</a>{action}</div></article>'''

