write('jobs/create.html','Post a Job','job-create',f'''
<div class="page-head"><div><h1>Post a Job</h1><p>For larger or longer work such as renovation, rewiring, waterproofing, full-house painting, major repairs or work requiring multiple workers.</p></div><a class="btn btn-secondary" href="index.html">{I('x')} Cancel</a></div><div class="callout neutral" style="margin-bottom:18px">{I('info')}<div><strong>Post one complete requirement</strong>You do not need to create separate work sections now. After comparing bids, you can select multiple vendors and split the work between them.</div></div>
<div class="layout-main"><section class="card form-card"><form class="needs-validation" data-success-target="job-success"><div class="form-section"><div class="form-section-head"><span class="section-number">1</span><div><h3>Basic Information</h3><p>Give your project a clear identity.</p></div></div><div class="form-grid"><div class="field full"><label>Job title <span class="required">*</span></label><input class="input" required placeholder="e.g. Full House Renovation"></div><div class="field"><label>Category <span class="required">*</span></label><select class="select" required><option value="">Select category</option><option>Renovation</option><option>Electrical</option><option>Waterproofing</option><option>Painting</option><option>Large Repair Work</option></select></div><div class="field"><label>Subcategory <span class="required">*</span></label><select class="select" required><option value="">Select subcategory</option><option>Residential Renovation</option><option>Commercial Renovation</option><option>Full Rewiring</option><option>Terrace Waterproofing</option></select></div></div></div>
<div class="form-section"><div class="form-section-head"><span class="section-number">2</span><div><h3>Job Details</h3><p>Vendors quote against this complete scope.</p></div></div><div class="form-grid"><div class="field full"><label>Detailed job description <span class="required">*</span></label><textarea class="textarea" required placeholder="Describe the current space, the desired outcome and any known constraints..."></textarea></div><div class="field full"><label>Required work <span class="required">*</span></label><textarea class="textarea" required placeholder="List the key work that needs to be completed..."></textarea></div><div class="field full"><label>Scope of work <span class="required">*</span></label><textarea class="textarea" required placeholder="Describe inclusions, exclusions, rooms, measurements or phases..."></textarea></div><div class="field"><label>Materials / details if applicable</label><textarea class="textarea" placeholder="Preferred brands, grades, finish or who supplies materials..."></textarea></div><div class="field"><label>Additional requirements</label><textarea class="textarea" placeholder="Site access, cleanup, safety or approval requirements..."></textarea></div></div></div>
<div class="form-section"><div class="form-section-head"><span class="section-number">3</span><div><h3>Budget</h3><p>Your expected budget is visible to bidding vendors.</p></div></div><div class="form-grid"><div class="field"><label>Expected budget <span class="required">*</span></label><div class="input-prefix"><span>₹</span><input class="input" required type="number" min="1000" placeholder="450000"></div></div><div class="field"><label>Budget type <span class="required">*</span></label><select class="select" required><option>Fixed budget</option><option>Budget range</option><option>Open to vendor estimate</option></select></div></div></div>
<div class="form-section"><div class="form-section-head"><span class="section-number">4</span><div><h3>Schedule</h3><p>Share your preferred working window.</p></div></div><div class="form-grid"><div class="field"><label>Preferred start date <span class="required">*</span></label><input class="input" type="date" required value="2026-09-01"></div><div class="field"><label>Expected completion date <span class="required">*</span></label><input class="input" type="date" required value="2026-10-15"></div><div class="field"><label>Required time</label><input class="input" placeholder="e.g. 6 weeks"></div><div class="field"><label>Shift availability</label><select class="select"><option>Day shift</option><option>Evening shift</option><option>Flexible</option><option>Weekend only</option></select></div><div class="field full"><label>Working hours</label><input class="input" placeholder="e.g. 9:00 AM to 6:00 PM, Monday–Saturday"></div></div></div>
<div class="form-section"><div class="form-section-head"><span class="section-number">5</span><div><h3>Location</h3><p>Provide the worksite information.</p></div></div><div class="form-grid"><div class="field full"><label>Address <span class="required">*</span></label><input class="input" required value="24, Lake View Residency, Morabadi"></div><div class="field"><label>City <span class="required">*</span></label><input class="input" required value="Ranchi"></div><div class="field"><label>Area <span class="required">*</span></label><input class="input" required value="Morabadi"></div><div class="field"><label>Pincode <span class="required">*</span></label><input class="input" required value="834008"></div><div class="field"><label>Location / map selection</label><button type="button" class="btn btn-secondary" style="width:100%" data-toast="Location pinned" data-toast-message="24, Lake View Residency has been selected.">{I('map')} Use current pin</button></div></div></div>
<div class="form-section"><div class="form-section-head"><span class="section-number">6</span><div><h3>Attachments</h3><p>Add images, documents or reference files.</p></div></div>{upload('job-files','image/*,.pdf,.doc,.docx,.xls,.xlsx')}</div>
<div class="form-section"><div class="form-section-head"><span class="section-number">7</span><div><h3>Contact</h3><p>Shared with selected vendors for coordination.</p></div></div><div class="form-grid"><div class="field"><label>user name <span class="required">*</span></label><input class="input" required value="Ananya Sharma"></div><div class="field"><label>Mobile number <span class="required">*</span></label><input class="input" required value="+91 98765 43210"></div></div></div><div class="form-actions"><a class="btn btn-secondary" href="index.html">Cancel</a><button type="button" class="btn btn-soft" data-save-draft>Save Draft</button><button type="submit" class="btn btn-primary">{I('briefcase')} Publish Job</button></div></form></section>
<aside class="stack"><section class="card"><div class="card-head"><h3>Tips for better bids</h3></div><div class="card-body"><div class="stack small"><div class="cell-user"><span class="stat-icon">{I('file')}</span><div><strong>Be specific</strong><div class="muted">Include dimensions and desired finish.</div></div></div><div class="cell-user"><span class="stat-icon teal">{I('image')}</span><div><strong>Add references</strong><div class="muted">Photos help vendors estimate effort.</div></div></div><div class="cell-user"><span class="stat-icon orange">{I('calendar')}</span><div><strong>Use realistic dates</strong><div class="muted">Allow time for sourcing materials.</div></div></div></div></div></section><div class="callout warning">{I('rupee')}<div><strong>Service payment is offline</strong>users pay vendors directly. Platform payments are only used by vendors for bidding credits or subscriptions.</div></div></aside></div>
<section class="card success-panel" id="job-success" hidden><span class="success-icon">{I('check')}</span><h2>Your job is live!</h2><p>Verified vendors can now review your complete job requirement and submit one locked quotation each.</p><div class="success-summary"><div class="info-item"><span class="info-label">Job ID</span><strong>JOB-2026-0442</strong></div><div class="info-item"><span class="info-label">Status</span>{badge('Open for Bidding','open')}</div><div class="info-item"><span class="info-label">Published</span><strong>20 Aug 2026, 11:31 AM</strong></div></div><div class="actions" style="justify-content:center"><a class="btn btn-secondary" href="index.html">My Jobs</a><a class="btn btn-primary" href="details.html">View Job</a></div></section>
''')

